// GitHub Action entry point.
//
// A Node action receives its inputs as INPUT_* environment variables and no
// argv, so this shim turns them into the CLI invocation and then loads the
// compiled runner. `dist/moongate.js` is generated by
// `moon build --target js --release`; do not edit it by hand.

const path = require("node:path");

function input(name, fallback) {
  const key = "INPUT_" + name.toUpperCase().replace(/ /g, "_");
  const value = process.env[key];
  return value === undefined || value === "" ? fallback : value;
}

function fail(message) {
  process.stdout.write("::error title=moongate::" + message + "\n");
  process.exit(2);
}

const base = input("base", "");
const head = input("head", "");
if (base === "" || head === "") {
  fail("Both 'base' and 'head' inputs are required.");
}

const repository = path.resolve(input("repository", "."));
try {
  process.chdir(repository);
} catch {
  fail("Cannot enter the repository directory.");
}

// The key reaches the runner through the environment only: never argv, never
// a file, never the log.
const apiKey = input("api-key", "");
if (apiKey !== "") {
  process.env.TYPESAFE_API_KEY = apiKey;
}
// The real variable name keeps the dash: GitHub only uppercases and replaces
// spaces. Deleting it stops the key from reaching the `git` child environment.
delete process.env["INPUT_API-KEY"];

// Policy always comes from the base commit: a pull request cannot weaken the
// rules that judge it. Configuration changes take effect after merge.
process.argv = [
  process.argv[0],
  __filename,
  "check",
  "--base",
  base,
  "--head",
  head,
  "--config",
  input("config", ".moongate.json"),
  "--config-ref",
  base,
  "--format",
  "github",
];

require("./moongate.js");
